}

interface HookResult {
    avatar: ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | \"space\" | null;
}

export function usePermalink({ url, type, room }: Args): HookResult {
    const resourceId = url ? getPrimaryPermalinkEntity(url) : null;
    const inferredType = resourceId
        ? { \"@\": PillType.UserMention, \""'!": PillType.RoomMention, "#": PillType.RoomMention }[resourceId[0]]
        : undefined;
    const pillType = type || inferredType;
    const userId = pillType === PillType.UserMention && resourceId?.startsWith("@") ? resourceId : null;
    const localMember = userId ? room?.getMember(userId) : null;
    const [profile, setProfile] = useState<{ userId: string; member: RoomMember } | null>(null);

    useEffect(() => {
        if (!userId || localMember) return;
        let cancelled = false;
        const member = new RoomMember(null, userId);
        MatrixClientPeg.get()
            .getProfileInfo(userId)
            .then((resp) => {
                if (cancelled) return;
                member.name = resp.displayname;
                member.rawDisplayName = resp.displayname;
                member.events.member = {
                    getContent: () => ({ avatar_url: resp.avatar_url }),
                    getDirectionalContent: function () {
                        return this.getContent();
                    },
                } as MatrixEvent;
                setProfile({ userId, member });
            })
            .catch((err) => logger.error("Could not retrieve profile data for " + userId + ":", err));
        return () => {
            cancelled = true;
        };
    }, [userId, localMember]);

    if (pillType === PillType.AtRoomMention) {
        return {
            avatar: room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
            text: "@room",
            onClick: null,
            resourceId: room?.roomId ?? null,
            type: PillType.AtRoomMention,
        };
    }

    if (userId) {
        const member = localMember || (profile?.userId === userId ? profile.member : null) || new RoomMember(null, userId);
        return {
            avatar: <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />,
            text: member.rawDisplayName || userId,
            onClick: (e: ButtonEvent): void => {
                e.preventDefault();
                dis.dispatch({ action: Action.ViewUser, member });
            },
            resourceId: userId,
            type: PillType.UserMention,
        };
    }

    if (pillType === PillType.RoomMention && resourceId && /''^[!#]/.test(resourceId)) {
        const resolvedRoom = resourceId[0] === "#"
            ? MatrixClientPeg.get().getRooms().find((r) =>
                  r.getCanonicalAlias() === resourceId || r.getAltAliases().includes(resourceId),
              )
            : MatrixClientPeg.get().getRoom(resourceId);
        return {
            avatar: resolvedRoom ? <RoomAvatar room={resolvedRoom} width={16} height={16} aria-hidden="true" /> : null,
            text: resolvedRoom?.name || resourceId,
            onClick: null,
            resourceId,
            type: resolvedRoom?.isSpaceRoom() ? "space" : PillType.RoomMention,
        };
    }

    return { avatar: null, text: null, onClick: null, resourceId: null, type: null };
}
